  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C09"],
      "claim": "Bicuculline, the closest structural analogue sharing the phthalideisoquinoline lactone, dimethoxybenzene, and methylenedioxy motifs, was directly shown to penetrate the brain in a dose-dependent manner in rats, providing strong transferable evidence that the query's core can cross the BBB.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "α-Allocryptopine, a related benzylisoquinoline alkaloid, was detected in rat CSF after administration, directly demonstrating BBB passage in the same alkaloid family.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Corydaline reached brain levels close to those in heart, lung, kidney, and spleen after oral dosing in rats, indicating effective CNS access for a close protoberberine-type analogue.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Hernandezine achieved brain concentrations nearly equal to plasma Cmax after intravenous dosing in rats, showing that this alkaloid family can achieve meaningful CNS exposure after systemic administration.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Pass: the query is a phthalideisoquinoline alkaloid (noscapine-like), and direct BBB-permeability evidence from the closest analogue bicuculline plus multiple structurally related alkaloids showing CSF and brain exposure supports meaningful CNS access after systemic administration.",
  "evidence_gaps": [
    "No direct quantitative brain/plasma or CSF measurement for the query itself is present in the supplied records, but qualitative permeability and tissue-distribution evidence from close analogues is strong.",
    "Potential efflux liability was not directly assessed for the query, but observed brain and CSF exposure in analogues indicates adequate CNS access despite possible transporter involvement."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

